"""Candidate symmetry-expansion rules, tested through the real ElasticDocument path."""
from __future__ import annotations
import numpy as np
from copy import deepcopy
from pymatgen.analysis.elasticity import Deformation, Strain
from pymatgen.core.tensors import TensorMapping
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer


def _ops(structure, symprec):
    return SpacegroupAnalyzer(structure, symprec=symprec).get_symmetry_operations(cartesian=True)


def rule_buggy(structure, deformations, stresses, uuids, job_dirs, symprec):
    """The shipped implementation (deformation-gradient dedup + is_independent)."""
    symmops = _ops(structure, symprec)
    full = [deepcopy(x) for x in (deformations, stresses, uuids, job_dirs)]
    mapping = TensorMapping()
    for i, defo in enumerate(deformations):
        mapping[defo] = True
        for op in symmops:
            rot = defo.transform(op)
            if rot in mapping:
                continue
            if not Deformation(rot).is_independent():
                continue
            mapping[rot] = True
            full[0].append(rot)
            full[1].append(stresses[i].transform(op))
            full[2].append(uuids[i])
            full[3].append(job_dirs[i])
    return tuple(full)


def rule_a(structure, deformations, stresses, uuids, job_dirs, symprec):
    """Dedup on strain, no independence filter."""
    symmops = _ops(structure, symprec)
    full = [list(deformations), list(stresses), list(uuids), list(job_dirs)]
    mapping = TensorMapping()
    for defo in deformations:
        mapping[Deformation(defo).green_lagrange_strain] = True
    for i, defo in enumerate(deformations):
        for op in symmops:
            rot = Deformation(defo.transform(op))
            strain = rot.green_lagrange_strain
            if strain in mapping:
                continue
            mapping[strain] = True
            full[0].append(rot)
            full[1].append(stresses[i].transform(op))
            full[2].append(uuids[i])
            full[3].append(job_dirs[i])
    return tuple(full)


def rule_b(structure, deformations, stresses, uuids, job_dirs, symprec):
    """Dedup on strain + only keep rotated strains with a single Voigt component."""
    symmops = _ops(structure, symprec)
    full = [list(deformations), list(stresses), list(uuids), list(job_dirs)]
    mapping = TensorMapping()
    for defo in deformations:
        mapping[Deformation(defo).green_lagrange_strain] = True
    for i, defo in enumerate(deformations):
        for op in symmops:
            rot = Deformation(defo.transform(op))
            strain = rot.green_lagrange_strain
            if strain in mapping:
                continue
            if np.count_nonzero(np.abs(strain.voigt) > 1e-8) != 1:
                continue
            mapping[strain] = True
            full[0].append(rot)
            full[1].append(stresses[i].transform(op))
            full[2].append(uuids[i])
            full[3].append(job_dirs[i])
    return tuple(full)


def _pattern(strain, tol=1e-8):
    voigt = np.asarray(strain.voigt)
    return tuple(np.nonzero(np.abs(voigt) > tol)[0].tolist())


def rule_c(structure, deformations, stresses, uuids, job_dirs, symprec):
    """Dedup on strain + keep rotations whose strain state is consistent per pattern."""
    symmops = _ops(structure, symprec)
    full = [list(deformations), list(stresses), list(uuids), list(job_dirs)]
    mapping = TensorMapping()
    states: dict[tuple, np.ndarray] = {}

    def register(strain):
        pattern = _pattern(strain)
        voigt = np.asarray(strain.voigt)
        direction = voigt / voigt[list(pattern)][np.argmax(np.abs(voigt[list(pattern)]))]
        states.setdefault(pattern, direction)
        return pattern, direction

    for defo in deformations:
        strain = Deformation(defo).green_lagrange_strain
        mapping[strain] = True
        register(strain)
    for i, defo in enumerate(deformations):
        for op in symmops:
            rot = Deformation(defo.transform(op))
            strain = rot.green_lagrange_strain
            if strain in mapping:
                continue
            pattern = _pattern(strain)
            voigt = np.asarray(strain.voigt)
            direction = voigt / voigt[list(pattern)][np.argmax(np.abs(voigt[list(pattern)]))]
            known = states.get(pattern)
            if known is not None and not np.allclose(known, direction, atol=1e-6):
                continue
            states.setdefault(pattern, direction)
            mapping[strain] = True
            full[0].append(rot)
            full[1].append(stresses[i].transform(op))
            full[2].append(uuids[i])
            full[3].append(job_dirs[i])
    return tuple(full)


RULES = {"buggy": rule_buggy, "A_nofilter": rule_a, "B_independent": rule_b, "C_states": rule_c}
